    report = _evolution()
    expected = _expected(report)
    expected["stages"][1]["at"] = "2022-03-15T00:00:00Z"
    assert (
        verify_bundle_evolution_checkpoint_bundle_evolution(report, expected)
        is False
    )


def test_expected_stage_count_mismatch_returns_false():
    report = _evolution()
    expected = _expected(report)
    expected["stages"] = expected["stages"][:2]
    assert (
        verify_bundle_evolution_checkpoint_bundle_evolution(report, expected)
